/**
 * env-config.js — Runtime environment configuration
 *
 * This file is served as a static asset and loaded BEFORE the Angular app
 * bootstraps (via <script> tag in index.html). It injects environment
 * variables from the server/container into the window object, allowing
 * the Angular app to read them at runtime without a rebuild.
 *
 * In Docker: this file is generated by docker-entrypoint.sh from
 * environment variables passed to the container.
 *
 * In Vercel/Netlify: use their environment variable injection or
 * a build-time replacement script.
 *
 * The Angular environment.ts files read from window.__env as a fallback:
 *   const url = window.__env?.SUPABASE_URL ?? 'YOUR_SUPABASE_URL';
 */

(function(window) {
  window.__env = window.__env || {};

  // These values are replaced at container startup by docker-entrypoint.sh
  // Defaults are empty strings — the app will show an error if not set
  window.__env.SUPABASE_URL      = '${SUPABASE_URL}';
  window.__env.SUPABASE_ANON_KEY = '${SUPABASE_ANON_KEY}';
  window.__env.VAPID_PUBLIC_KEY  = '${VAPID_PUBLIC_KEY}';
  window.__env.APP_VERSION       = '${APP_VERSION}';
  window.__env.ENVIRONMENT       = '${ENVIRONMENT}';

}(window));
